<template>
  <view v-if="pageReady" class="medication-page" data-testid="medication-workspace">
    <view class="shell">
      <view class="topbar"><button class="back" aria-label="返回我的" data-testid="medication-back" @click="goBack">‹</button><text class="top-title">用药管理</text><button v-if="view === 'plans'" class="add" aria-label="新增本人用药计划" data-testid="medication-add" @click="startPlanCreate">＋</button><view v-else class="spacer" /></view>
      <view v-if="view === 'plans' || view === 'today' || view === 'history'" class="tabs" role="tablist" aria-label="用药页面分类">
        <button v-for="item in tabItems" :key="item.value" class="tab" :class="{ 'tab--active': tab === item.value }" :aria-selected="tab === item.value" @click="selectTab(item.value)">{{ item.label }}</button>
      </view>

      <view v-if="problemMessage" class="problem" role="alert" aria-live="polite"><text>{{ problemMessage }}</text><text v-if="requestId" class="request-id">请求编号：{{ requestId }}</text><button v-if="refreshPlanId" class="inline" @click="openPlan(refreshPlanId)">重新读取服务器状态</button></view>
      <view v-if="loading" class="status" role="status" aria-busy="true"><DashboardDataStatus state="loading" test-id="medication-loading" /></view>
      <view v-else-if="loadError" class="status" role="alert"><DashboardDataStatus state="error" :message="loadError" :retryable="true" :busy="busy" test-id="medication-error" @retry="reloadCurrent" /><text v-if="requestId" class="request-id">请求编号：{{ requestId }}</text></view>

      <template v-else-if="view === 'plans'">
        <view class="intro"><text class="eyebrow">YOUR PLAN</text><text class="heading">用药计划</text><text class="copy">仅记录本人或专业人员已确定的安排；此处不提供处方建议。</text></view>
        <view v-if="plans.length === 0" class="empty" data-testid="medication-plans-empty"><text class="empty-mark">＋</text><text class="card-title">暂无用药计划</text><text class="copy">没有计划不代表需要开始用药。</text><GcButton label="记录一项本人计划" test-id="medication-empty-create" @click="startPlanCreate" /></view>
        <view v-else class="list" data-testid="medication-plans-list">
          <button v-for="plan in plans" :key="plan.id" class="plan-card" :data-testid="`medication-plan-${plan.id}`" @click="openPlan(plan.id)">
            <view class="card-top"><text class="card-title">{{ plan.medication_name }}</text><text class="version">第 {{ plan.record_version }} 版</text></view>
            <text v-if="plan.dosage_text" class="card-copy">{{ plan.dosage_text }}</text>
            <view class="badges"><text class="badge">{{ confirmationLabel(plan.confirmation_status) }}</text><text class="badge">{{ planStatusLabel(plan.plan_status) }}</text><text v-if="plan.source_deleted" class="badge badge--muted">来源已删除</text></view>
          </button>
        </view>
      </template>

      <template v-else-if="view === 'today'">
        <view class="intro"><text class="eyebrow">TODAY</text><text class="heading">今日用药安排</text><text class="copy">“待确认”只表示尚未记录回应，不代表未服用。</text></view>
        <view v-if="checkins.length === 0" class="empty" data-testid="medication-today-empty"><text class="empty-mark">○</text><text class="card-title">今日暂无已载入的打卡安排</text><text class="copy">这不代表需要用药或已经完成服用。</text><GcButton label="查看用药计划" variant="secondary" test-id="medication-today-plans" @click="selectTab('plans')" /></view>
        <view v-else class="list" data-testid="medication-today-list">
          <view v-for="checkin in checkins" :key="checkin.id" class="checkin-card" :data-testid="`medication-checkin-${checkin.id}`">
            <view class="card-top"><text class="card-title">{{ localScheduleTime(checkin.scheduled_for) }}</text><text class="badge" :class="statusClass(checkin.status)">{{ checkinStatusLabel(checkin.status) }}</text></view>
            <text class="card-copy">{{ checkin.local_date }} · 安排时间（时区按本人计划）</text>
            <text v-if="checkin.status === 'taken' && checkin.taken_at" class="card-copy">记录的实际时间：{{ localScheduleTime(checkin.taken_at) }}</text>
            <GcButton :label="checkin.status === 'pending' ? '记录回应' : '查看 / 更正记录'" variant="secondary" :disabled="busy" :test-id="`medication-checkin-edit-${checkin.id}`" @click="startCheckinEdit(checkin)" />
          </view>
        </view>
      </template>

      <template v-else-if="view === 'history'">
        <view class="intro"><text class="eyebrow">HISTORY</text><text class="heading">打卡历史</text><text class="copy">按本人时区查看所选日期范围的打卡记录。</text></view>
        <view class="range-card"><view class="field"><text class="label">开始日期</text><picker mode="date" :value="historyStart" @change="setHistoryStart"><view class="input">{{ historyStart }}</view></picker></view><view class="field"><text class="label">结束日期</text><picker mode="date" :value="historyEnd" @change="setHistoryEnd"><view class="input">{{ historyEnd }}</view></picker></view><GcButton label="查询历史" :busy="busy" :disabled="busy" test-id="medication-history-load" @click="loadHistory" /></view>
        <view v-if="historyLoaded && history.length === 0" class="empty" data-testid="medication-history-empty"><text class="card-title">所选范围暂无打卡记录</text><text class="copy">空记录不表示未服用。</text></view>
        <view v-else-if="history.length" class="list" data-testid="medication-history-list"><view v-for="checkin in history" :key="checkin.id" class="checkin-card"><view class="card-top"><text class="card-title">{{ localScheduleTime(checkin.scheduled_for) }}</text><text class="badge" :class="statusClass(checkin.status)">{{ checkinStatusLabel(checkin.status) }}</text></view><text class="card-copy">{{ checkin.local_date }} · 打卡版本 {{ checkin.record_version }}</text><text v-if="checkin.status === 'taken' && checkin.taken_at" class="card-copy">实际服用时间：{{ localScheduleTime(checkin.taken_at) }}</text><text v-if="checkin.note" class="card-copy">本人备注：{{ checkin.note }}</text><GcButton label="查看 / 更正" variant="secondary" :disabled="busy" test-id="medication-history-edit" @click="startCheckinEdit(checkin)" /></view></view>
      </template>

      <template v-else-if="view === 'detail' && currentPlan">
        <view class="intro"><text class="eyebrow">本人计划</text><text class="heading">{{ currentPlan.medication_name }}</text><text class="copy">{{ confirmationLabel(currentPlan.confirmation_status) }} · {{ planStatusLabel(currentPlan.plan_status) }} · 第 {{ currentPlan.record_version }} 版</text></view>
        <view class="detail-card"><text class="label">剂量原文</text><text class="detail-value">{{ currentPlan.dosage_text || '未填写' }}</text><text class="label">给药途径代码</text><text class="detail-value">{{ currentPlan.route_code || '未填写' }}</text><text class="label">计划日期</text><text class="detail-value">{{ currentPlan.start_date || '未设置' }} 至 {{ currentPlan.end_date || '未设置' }}</text><text class="label">来源</text><text class="detail-value">{{ currentPlan.source_type === 'manual' ? '本人手动记录' : '医疗档案' }}<template v-if="currentPlan.source_deleted">（来源已删除）</template></text><text class="label">计划边界</text><text class="detail-value">可用操作以服务器状态为准；不会推断或更改处方剂量。</text></view>
        <view class="section-head"><text class="card-title">计划日程</text><GcButton label="添加日程" variant="secondary" test-id="medication-schedule-add" :disabled="busy" @click="startScheduleCreate" /></view>
        <view v-if="schedules.length === 0" class="empty compact" data-testid="medication-schedules-empty"><text class="card-title">尚无日程</text><text class="copy">添加本人已确定的提醒时间，不会自动判断是否应服药。</text></view>
        <view v-else class="list" data-testid="medication-schedules-list"><view v-for="schedule in schedules" :key="schedule.id" class="checkin-card"><view class="card-top"><text class="card-title">{{ schedule.local_time.slice(0, 5) }}</text><text class="badge">{{ schedule.enabled ? '已启用' : '已停用' }}</text></view><text class="card-copy">{{ schedule.timezone }} · {{ schedule.valid_from }} 至 {{ schedule.valid_to || '未设结束' }}</text><text class="card-copy">{{ schedule.rrule || '单次日程' }}</text><view class="row-actions"><GcButton label="编辑" variant="secondary" :disabled="busy" test-id="medication-schedule-edit" @click="startScheduleEdit(schedule)" /><GcButton label="停用日程" variant="danger" :disabled="busy || !schedule.enabled" test-id="medication-schedule-disable" @click="disableSchedule(schedule)" /></view></view></view>
        <view class="actions">
          <GcButton label="编辑计划" variant="secondary" test-id="medication-plan-edit" :disabled="busy" @click="startPlanEdit" />
          <GcButton v-for="action in allowedPlanActions(currentPlan)" :key="action" :label="actionLabel(action)" :variant="action === 'discontinue' ? 'danger' : 'primary'" :busy="busy" :disabled="busy" :test-id="`medication-transition-${action}`" @click="transitionPlan(action)" />
          <GcButton label="删除计划" variant="danger" test-id="medication-plan-delete-open" :disabled="busy" @click="deletePlanPrompt = true" />
        </view>
      </template>

      <template v-else-if="view === 'plan-form'">
        <view class="intro"><text class="eyebrow">{{ editingPlan ? 'EDIT PLAN' : 'NEW PLAN' }}</text><text class="heading">{{ editingPlan ? '编辑本人计划' : '记录本人用药计划' }}</text><text class="copy">只填写已由本人或专业人员确定的信息。不会推荐药品、推断剂量或修改处方。</text></view>
        <view v-if="planError" class="field-error" role="alert">{{ planError }}</view>
        <view v-if="planConflict || planConflictPending" class="conflict" role="status" aria-live="polite" data-testid="medication-plan-conflict"><text class="conflict-title">计划已在其他位置更新</text><text>本地草稿仍保留；不会自动覆盖或重新提交。</text><text>本地草稿：{{ planDraftSummary }}</text><template v-if="planConflict"><text>服务器最新：{{ planConflict.medication_name }} · 第 {{ planConflict.record_version }} 版</text><view class="actions"><GcButton label="放弃草稿并载入最新" variant="secondary" :disabled="busy" test-id="medication-plan-conflict-discard" @click="discardPlanConflict" /><GcButton label="保留草稿并使用最新版本" :disabled="busy" test-id="medication-plan-conflict-keep" @click="keepPlanDraft" /></view></template><template v-else><text>尚未能读取服务器最新版本；保存已锁定。</text><GcButton label="重试读取最新计划" variant="secondary" :disabled="busy" test-id="medication-plan-conflict-retry" @click="retryPlanConflictLatest" /></template><text v-if="requestId" class="request-id">请求编号：{{ requestId }}</text></view>
        <view v-if="planRebased" class="notice" role="status">草稿已保留。核对字段后，再次手动点击保存才会提交。</view>
        <view class="form-card"><view class="field"><text class="label">药品名称 <text class="required">*</text></text><input v-model="planDraft.medicationName" class="input" maxlength="160" aria-label="药品名称" data-testid="medication-name" /></view><view class="field"><text class="label">剂量原文（可选）</text><input v-model="planDraft.dosageText" class="input" maxlength="160" placeholder="按本人已确认来源原文填写" aria-label="剂量原文" data-testid="medication-dosage" /></view><view class="field"><text class="label">给药途径代码（可选）</text><input v-model="planDraft.routeCode" class="input" maxlength="32" aria-label="给药途径代码" data-testid="medication-route" /></view><view class="field"><text class="label">开始日期（可选）</text><picker mode="date" :value="planDraft.startDate" @change="setPlanDate('startDate', $event)"><view class="input">{{ planDraft.startDate || '未设置' }}</view></picker></view><view class="field"><text class="label">结束日期（可选）</text><picker mode="date" :value="planDraft.endDate" @change="setPlanDate('endDate', $event)"><view class="input">{{ planDraft.endDate || '未设置' }}</view></picker></view><view class="notice">新计划先处于待确认且未启用状态。此表单仅支持本人手动记录；不会读取或伪造医疗档案来源。</view><view class="actions"><GcButton :label="editingPlan ? (planRebased ? '确认保存草稿' : '保存修改') : '保存计划'" :busy="busy" :disabled="busy || Boolean(planConflict) || planConflictPending" test-id="medication-plan-save" @click="savePlan" /><GcButton label="取消" variant="secondary" :disabled="busy" test-id="medication-plan-cancel" @click="cancelForm" /></view></view>
      </template>

      <template v-else-if="view === 'schedule-form'">
        <view class="intro"><text class="eyebrow">SCHEDULE</text><text class="heading">{{ editingSchedule ? '编辑本人日程' : '添加本人日程' }}</text><text class="copy">只录入已确定的本地时间与重复规则；IANA 时区、重复规则及夏令时由服务器校验。</text></view>
        <view v-if="scheduleError" class="field-error" role="alert">{{ scheduleError }}</view>
        <view v-if="scheduleConflict || scheduleConflictPending" class="conflict" role="status" data-testid="medication-schedule-conflict"><text class="conflict-title">日程已更新；草稿已保留</text><template v-if="scheduleConflict"><text>服务器最新：{{ scheduleConflict.local_time }} · {{ scheduleConflict.timezone }} · 第 {{ scheduleConflict.record_version }} 版</text><view class="actions"><GcButton label="放弃草稿并载入最新" variant="secondary" :disabled="busy" test-id="medication-schedule-conflict-discard" @click="discardScheduleConflict" /><GcButton label="保留草稿并使用最新版本" :disabled="busy" test-id="medication-schedule-conflict-keep" @click="keepScheduleDraft" /></view></template><template v-else><text>尚未能读取服务器最新版本；保存已锁定。</text><GcButton label="重试读取最新日程" variant="secondary" :disabled="busy" test-id="medication-schedule-conflict-retry" @click="retryScheduleConflictLatest" /></template></view>
        <view class="form-card"><view class="field"><text class="label">本地时间</text><picker mode="time" :value="scheduleDraft.localTime" @change="setScheduleTime"><view class="input">{{ scheduleDraft.localTime || '选择时间' }}</view></picker></view><view class="field"><text class="label">IANA 时区</text><input v-model="scheduleDraft.timezone" class="input" maxlength="64" placeholder="例如 Asia/Shanghai" data-testid="medication-timezone" /></view><view class="field"><text class="label">重复规则（可空；服务端受限子集）</text><input v-model="scheduleDraft.rrule" class="input" maxlength="256" placeholder="FREQ=DAILY 或 FREQ=WEEKLY;BYDAY=MO,WE,FR" data-testid="medication-rrule" /></view><view class="notice">支持 DAILY、WEEKLY、INTERVAL、BYDAY、COUNT、UNTIL 的受限组合；不合法规则会由服务端拒绝。空规则表示单次。</view><view class="field"><text class="label">生效日期</text><picker mode="date" :value="scheduleDraft.validFrom" @change="setScheduleDate('validFrom', $event)"><view class="input">{{ scheduleDraft.validFrom }}</view></picker></view><view class="field"><text class="label">结束日期（可选）</text><picker mode="date" :value="scheduleDraft.validTo" @change="setScheduleDate('validTo', $event)"><view class="input">{{ scheduleDraft.validTo || '未设置' }}</view></picker></view><view v-if="editingSchedule" class="field"><text class="label">日程状态</text><view class="choice-row"><button class="choice" :class="{ selected: scheduleDraft.enabled }" @click="scheduleDraft.enabled = true">启用</button><button class="choice" :class="{ selected: !scheduleDraft.enabled }" @click="scheduleDraft.enabled = false">停用</button></view></view><view v-if="scheduleRebased" class="notice">草稿已保留，请核对并再次手动确认保存。</view><view class="actions"><GcButton :label="editingSchedule ? '保存日程修改' : '保存日程'" :busy="busy" :disabled="busy || Boolean(scheduleConflict) || scheduleConflictPending" test-id="medication-schedule-save" @click="saveSchedule" /><GcButton label="取消" variant="secondary" :disabled="busy" test-id="medication-schedule-cancel" @click="cancelForm" /></view></view>
      </template>

      <view v-if="checkinEdit" class="backdrop" role="presentation" @click.self="checkinEdit = null"><view class="modal" role="dialog" aria-modal="true" aria-labelledby="checkin-edit-title" data-testid="medication-checkin-editor"><text id="checkin-edit-title" class="card-title">记录打卡回应</text><text class="copy">安排时间：{{ localScheduleTime(checkinEdit.scheduled_for) }}。待确认不等于未服用。</text><view class="field"><text class="label">状态</text><view class="choice-row"><button v-for="status in checkinStatuses" :key="status" class="choice" :class="{ selected: checkinDraft.status === status }" :aria-pressed="checkinDraft.status === status" @click="setCheckinStatus(status)">{{ checkinStatusLabel(status) }}</button></view></view><view v-if="checkinDraft.status === 'taken'" class="field"><text class="label">实际服用时间（含本地时区）</text><input v-model="checkinDraft.takenAt" class="input" type="text" placeholder="2026-10-18T08:30+08:00" data-testid="medication-taken-at" /><text class="hint">按本人实际记录填写，格式需包含时区；不预填当前时间。</text></view><view class="field"><text class="label">本人备注（可选）</text><textarea v-model="checkinDraft.note" class="textarea" maxlength="500" data-testid="medication-checkin-note" /></view><view v-if="checkinConflict || checkinConflictPending" class="conflict" role="status" data-testid="medication-checkin-conflict"><template v-if="checkinConflict"><text>服务器最新状态：{{ checkinStatusLabel(checkinConflict.status) }} · 第 {{ checkinConflict.record_version }} 版</text><view class="actions"><GcButton label="放弃填写并载入最新" variant="secondary" :disabled="busy" test-id="medication-checkin-conflict-discard" @click="discardCheckinDraft" /><GcButton label="保留填写并使用最新版本" :disabled="busy" test-id="medication-checkin-conflict-keep" @click="keepCheckinDraft" /></view></template><template v-else><text>尚未能读取服务器最新打卡；当前填写仍保留且保存已锁定。</text><GcButton label="重试读取最新打卡" variant="secondary" :disabled="busy" test-id="medication-checkin-conflict-retry" @click="retryCheckinConflictLatest" /></template><text>本地填写仍保留。不会自动覆盖或重提。</text></view><text v-if="checkinError" class="field-error" role="alert">{{ checkinError }}</text><view class="actions"><GcButton label="确认保存打卡" :busy="busy" :disabled="busy || Boolean(checkinConflict) || checkinConflictPending" test-id="medication-checkin-save" @click="saveCheckin" /><GcButton label="取消" variant="secondary" :disabled="busy" test-id="medication-checkin-cancel" @click="closeCheckin" /></view></view></view>
      <view v-if="deletePlanPrompt" class="backdrop" role="presentation" @click.self="deletePlanPrompt = false"><view class="modal" role="dialog" aria-modal="true" aria-labelledby="medication-delete-title"><text id="medication-delete-title" class="card-title">删除本人计划？</text><text class="copy">未来安排将停止；历史打卡保留。此操作不会判断治疗是否结束。</text><view class="actions"><GcButton label="取消" variant="secondary" test-id="medication-plan-delete-cancel" @click="deletePlanPrompt = false" /><GcButton label="确认删除计划" variant="danger" :busy="busy" :disabled="busy" test-id="medication-plan-delete-confirm" @click="deletePlan" /></view></view></view>
    </view>
  </view>
  <view v-else class="auth-pending" role="status" aria-live="polite">正在验证会话…</view>
</template>

<script setup lang="ts">
import { computed, inject, reactive, ref } from 'vue'
import { onBackPress, onLoad, onShow } from '@dcloudio/uni-app'
import { AppError } from '../../api/errors'
import { appRouterKey, medicationApiKey } from '../../api/context'
import { canRenderRoute } from '../../navigation/routes'
import type { MedicationWorkspaceRouteName } from '../../navigation/routes'
import type { MedicationCheckin, MedicationPlan, MedicationPlanTransition, MedicationSchedule } from '../../api/openapiTypes'
import { allowedPlanActions, buildCheckinUpdate, buildPlanCreate, buildPlanPatch, buildScheduleWrite, checkinToDraft, planToDraft, scheduleToDraft } from '../../api/medicationForm'
import type { MedicationCheckinDraft, MedicationPlanDraft, MedicationScheduleDraft } from '../../api/medicationForm'
import { useAuthStore } from '../../stores/auth'
import DashboardDataStatus from '../../components/DashboardDataStatus.vue'
import GcButton from '../../components/GcButton.vue'

const routeName: MedicationWorkspaceRouteName = 'medications'
const auth = useAuthStore()
const router = inject(appRouterKey)
const api = inject(medicationApiKey)
const pageReady = ref(false)
const initialLoadStarted = ref(false)
const busy = ref(false)
const loading = ref(false)
const loadError = ref('')
const problemMessage = ref('')
const requestId = ref('')
const refreshPlanId = ref('')
const tab = ref<'plans' | 'today' | 'history'>('plans')
const view = ref<'plans' | 'today' | 'history' | 'detail' | 'plan-form' | 'schedule-form'>('plans')
const plans = ref<MedicationPlan[]>([])
const currentPlan = ref<MedicationPlan | null>(null)
const schedules = ref<MedicationSchedule[]>([])
const checkins = ref<MedicationCheckin[]>([])
const history = ref<MedicationCheckin[]>([])
const historyLoaded = ref(false)
const historyStart = ref(zoneDate(-29))
const historyEnd = ref(zoneDate(0))
const editingPlan = ref(false)
const planDraft = reactive<MedicationPlanDraft>({ medicationName: '', dosageText: '', routeCode: '', startDate: '', endDate: '' })
const planError = ref('')
const planConflict = ref<MedicationPlan | null>(null)
const planConflictPending = ref(false)
const planRebased = ref(false)
const scheduleDraft = reactive<MedicationScheduleDraft>({ localTime: '', timezone: auth.profile?.timezone ?? 'UTC', rrule: '', validFrom: zoneDate(0), validTo: '', enabled: true })
const editingSchedule = ref(false)
const currentSchedule = ref<MedicationSchedule | null>(null)
const scheduleError = ref('')
const scheduleConflict = ref<MedicationSchedule | null>(null)
const scheduleConflictPending = ref(false)
const scheduleRebased = ref(false)
const checkinEdit = ref<MedicationCheckin | null>(null)
const checkinDraft = reactive<MedicationCheckinDraft>({ status: 'pending', takenAt: '', note: '' })
const checkinError = ref('')
const checkinConflict = ref<MedicationCheckin | null>(null)
const checkinConflictPending = ref(false)
const deletePlanPrompt = ref(false)
const tabItems = [{ value: 'plans' as const, label: '计划' }, { value: 'today' as const, label: '今日打卡' }, { value: 'history' as const, label: '历史' }]
const checkinStatuses = ['taken', 'not_taken', 'pending', 'skipped'] as const
const planDraftSummary = computed(() => `${planDraft.medicationName} · ${planDraft.dosageText || '未填写剂量原文'} · ${planDraft.startDate || '未设开始日期'} 至 ${planDraft.endDate || '未设结束日期'}`)

onLoad((options) => {
  if (!canRenderRoute(routeName, auth.state)) { router?.requireAuthentication(routeName); return }
  pageReady.value = true
  const planId = typeof options?.plan_id === 'string' && /^[0-9a-f-]{36}$/i.test(options.plan_id) ? options.plan_id : ''
  initialLoadStarted.value = true
  if (planId) void openPlan(planId)
  else void loadPlans()
})
let firstShowPending = true
onShow(() => {
  if (!canRenderRoute(routeName, auth.state)) { if (pageReady.value) router?.requireAuthentication(routeName); return }
  if (pageReady.value && initialLoadStarted.value) {
    if (firstShowPending) { firstShowPending = false; return }
    void reloadCurrent()
  }
})
onBackPress(() => { goBack(); return true })

function goBack() { if (checkinEdit.value) { closeCheckin(); return }; if (deletePlanPrompt.value) { deletePlanPrompt.value = false; return }; if (view.value === 'plan-form' || view.value === 'schedule-form') { cancelForm(); return }; if (view.value === 'detail') { currentPlan.value = null; schedules.value = []; view.value = 'plans'; void loadPlans(); return }; router?.switchTab('me') }
function selectTab(value: 'plans' | 'today' | 'history') { tab.value = value; currentPlan.value = null; schedules.value = []; view.value = value; problemMessage.value = ''; loadError.value = ''; if (value === 'plans') void loadPlans(); else if (value === 'today') void loadToday(); else void loadHistory() }
async function reloadCurrent() { if (view.value === 'detail' && currentPlan.value) await openPlan(currentPlan.value.id); else if (tab.value === 'plans') await loadPlans(); else if (tab.value === 'today') await loadToday(); else if (tab.value === 'history') await loadHistory() }
async function loadPlans() { if (!api || !canRenderRoute(routeName, auth.state)) return; beginLoad(); try { plans.value = await api.listPlans(); loadError.value = '' } catch (error) { setError(error, '暂时无法载入用药计划。'); } finally { loading.value = false } }
