async function openPlan(id: string) { if (!api || !canRenderRoute(routeName, auth.state)) return; refreshPlanId.value = ''; beginLoad(); try { const [plan, items] = await Promise.all([api.getPlan(id), api.listSchedules(id)]); currentPlan.value = plan; schedules.value = items; tab.value = 'plans'; view.value = 'detail'; loadError.value = '' } catch (error) { setError(error, '暂时无法载入这项用药计划。'); refreshPlanId.value = id } finally { loading.value = false } }
function beginLoad() { loading.value = true; loadError.value = ''; problemMessage.value = ''; requestId.value = '' }
function setError(error: unknown, fallback: string) { loadError.value = fallback; problemMessage.value = error instanceof AppError ? errorMessage(error) : error ? fallback : ''; requestId.value = error instanceof AppError ? error.requestId ?? '' : '' }
function errorMessage(error: AppError) { if (error.status === 409) return '服务器状态已变化，当前内容未自动覆盖；请重新载入并核对。'; if (error.status === 422) return '部分内容不符合服务端校验，请核对后再试。'; if (error.status === 404) return '此资源当前不可用。'; if (error.status === 429) return '请求过于频繁，请稍后重试。'; if (error.status && error.status >= 500) return '服务暂时不可用，请稍后重试。'; if (error.kind === 'offline' || error.kind === 'network' || error.kind === 'timeout') return '网络暂不可用；没有记录任何成功状态。'; return '操作未完成，请稍后重试。' }
function confirmationLabel(status: MedicationPlan['confirmation_status']) { return ({ pending: '待确认', confirmed: '已确认', needs_review: '需复核' })[status] }
function planStatusLabel(status: MedicationPlan['plan_status']) { return ({ active: '使用中', ended: '已结束', discontinued: '未启用 / 已停用' })[status] }
function checkinStatusLabel(status: MedicationCheckin['status']) { return ({ taken: '已服用', not_taken: '本人记录未服用', pending: '待确认', skipped: '已跳过' })[status] }
function statusClass(status: MedicationCheckin['status']) { return status === 'taken' ? 'badge--success' : status === 'not_taken' ? 'badge--warning' : status === 'skipped' ? 'badge--muted' : '' }
function actionLabel(action: MedicationPlanTransition['action']) { return ({ confirm: '确认计划', review: '标记需复核', activate: '启用已确认计划', end: '结束计划', discontinue: '停用计划' })[action] }
function localScheduleTime(value: string) { return new Date(value).toLocaleString('zh-CN', { timeZone: auth.profile?.timezone || 'UTC', dateStyle: 'medium', timeStyle: 'short' }) }
function zoneDate(offset: number) { const zone = auth.profile?.timezone || 'UTC'; const parts = new Intl.DateTimeFormat('en-CA', { timeZone: zone, year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(new Date()); const year = Number(parts.find((part) => part.type === 'year')?.value); const month = Number(parts.find((part) => part.type === 'month')?.value); const day = Number(parts.find((part) => part.type === 'day')?.value); const shifted = new Date(Date.UTC(year, month - 1, day + offset)); return `${shifted.getUTCFullYear()}-${String(shifted.getUTCMonth() + 1).padStart(2, '0')}-${String(shifted.getUTCDate()).padStart(2, '0')}` }
function setHistoryStart(event: { detail?: { value?: string } }) { if (event.detail?.value) historyStart.value = event.detail.value }
function setHistoryEnd(event: { detail?: { value?: string } }) { if (event.detail?.value) historyEnd.value = event.detail.value }
function setPlanDate(key: 'startDate' | 'endDate', event: { detail?: { value?: string } }) { if (event.detail?.value) planDraft[key] = event.detail.value }
function startPlanCreate() { currentPlan.value = null; editingPlan.value = false; planConflict.value = null; planConflictPending.value = false; planRebased.value = false; planError.value = ''; Object.assign(planDraft, { medicationName: '', dosageText: '', routeCode: '', startDate: '', endDate: '' }); view.value = 'plan-form' }
