function cancelForm() { planError.value = ''; scheduleError.value = ''; planConflict.value = null; scheduleConflict.value = null; planConflictPending.value = false; scheduleConflictPending.value = false; planRebased.value = false; scheduleRebased.value = false; view.value = currentPlan.value ? 'detail' : 'plans' }
let lastPlanSignature = ''; let lastPlanKey = ''
function stableKey(signature: string, previous: { signature: string; key: string }) { if (signature !== previous.signature) { previous.signature = signature; previous.key = globalThis.crypto?.randomUUID?.() ?? `${Date.now()}-${Math.random().toString(36).slice(2)}` }; return previous.key }
async function savePlan() { if (!api || busy.value || planConflictPending.value || planConflict.value || !canRenderRoute(routeName, auth.state)) return; planError.value = ''; const result = editingPlan.value && currentPlan.value ? buildPlanPatch(planDraft, currentPlan.value) : buildPlanCreate(planDraft); if (!result.ok) { planError.value = result.message; return }; busy.value = true; try { const saved = editingPlan.value && currentPlan.value ? await api.updatePlan(currentPlan.value.id, result.body as import('../../api/openapiTypes').MedicationPlanPatch) : await api.createPlan(result.body as import('../../api/openapiTypes').MedicationPlanCreate, stableKey(JSON.stringify(result.body), { get signature() { return lastPlanSignature }, set signature(value) { lastPlanSignature = value }, get key() { return lastPlanKey }, set key(value) { lastPlanKey = value } })); lastPlanSignature = ''; lastPlanKey = ''; currentPlan.value = saved; plans.value = [saved, ...plans.value.filter((item) => item.id !== saved.id)]; planConflict.value = null; planConflictPending.value = false; planRebased.value = false; view.value = 'detail'; schedules.value = await api.listSchedules(saved.id).catch(() => []); } catch (error) { if (editingPlan.value && currentPlan.value && error instanceof AppError && error.status === 409) { planError.value = errorMessage(error); requestId.value = error.requestId ?? ''; planConflictPending.value = true; await retryPlanConflictLatest(true) } else { setError(error, '计划未保存；字段草稿仍保留。'); planError.value = loadError.value } } finally { busy.value = false } }
async function retryPlanConflictLatest(force = false) { if (!api || !currentPlan.value || (busy.value && !force)) return; try { planConflict.value = await api.getPlan(currentPlan.value.id); planConflictPending.value = false; planError.value = '' } catch (error) { planConflictPending.value = true; planConflict.value = null; planError.value = '读取最新计划失败；本地草稿仍保留，保存已锁定。'; requestId.value = error instanceof AppError ? error.requestId ?? '' : '' } }
function discardPlanConflict() { if (!planConflict.value) return; currentPlan.value = planConflict.value; Object.assign(planDraft, planToDraft(planConflict.value)); planConflict.value = null; planConflictPending.value = false; planRebased.value = false; planError.value = '' }
function keepPlanDraft() { if (!planConflict.value) return; currentPlan.value = planConflict.value; planConflict.value = null; planConflictPending.value = false; planRebased.value = true; planError.value = '' }
async function transitionPlan(action: MedicationPlanTransition['action']) { if (!api || !currentPlan.value || busy.value || !allowedPlanActions(currentPlan.value).includes(action)) return; busy.value = true; problemMessage.value = ''; try { const body: MedicationPlanTransition = { action, record_version: currentPlan.value.record_version }; const signature = `${currentPlan.value.id}:${JSON.stringify(body)}`; const saved = await api.transitionPlan(currentPlan.value.id, body, stableKey(signature, { get signature() { return lastTransitionSignature }, set signature(value) { lastTransitionSignature = value }, get key() { return lastTransitionKey }, set key(value) { lastTransitionKey = value } })); lastTransitionSignature = ''; lastTransitionKey = ''; currentPlan.value = saved; plans.value = plans.value.map((item) => item.id === saved.id ? saved : item); schedules.value = await api.listSchedules(saved.id).catch(() => schedules.value) } catch (error) { setError(error, '状态未改变。请读取服务器当前状态后再操作。'); refreshPlanId.value = currentPlan.value?.id ?? '' } finally { busy.value = false } }
let lastTransitionSignature = ''; let lastTransitionKey = ''
