function startScheduleCreate() { if (!currentPlan.value) return; editingSchedule.value = false; currentSchedule.value = null; scheduleConflict.value = null; scheduleConflictPending.value = false; scheduleRebased.value = false; scheduleError.value = ''; Object.assign(scheduleDraft, { localTime: '', timezone: auth.profile?.timezone || 'UTC', rrule: '', validFrom: zoneDate(0), validTo: '', enabled: true }); view.value = 'schedule-form' }
function startScheduleEdit(schedule: MedicationSchedule) { editingSchedule.value = true; currentSchedule.value = schedule; Object.assign(scheduleDraft, scheduleToDraft(schedule)); scheduleConflict.value = null; scheduleConflictPending.value = false; scheduleRebased.value = false; scheduleError.value = ''; view.value = 'schedule-form' }
function setScheduleTime(event: { detail?: { value?: string } }) { if (event.detail?.value) scheduleDraft.localTime = event.detail.value }
function setScheduleDate(key: 'validFrom' | 'validTo', event: { detail?: { value?: string } }) { if (event.detail?.value) scheduleDraft[key] = event.detail.value }
let lastScheduleSignature = ''; let lastScheduleKey = ''
async function saveSchedule() { if (!api || !currentPlan.value || busy.value || scheduleConflictPending.value || scheduleConflict.value) return; scheduleError.value = ''; const result = buildScheduleWrite(scheduleDraft, editingSchedule.value ? currentSchedule.value?.record_version : undefined); if (!result.ok) { scheduleError.value = result.message; return }; busy.value = true; try { const saved = editingSchedule.value && currentSchedule.value ? await api.updateSchedule(currentSchedule.value.id, result.body as import('../../api/openapiTypes').MedicationSchedulePatch) : await api.createSchedule(currentPlan.value.id, result.body as import('../../api/openapiTypes').MedicationScheduleWrite, stableKey(JSON.stringify(result.body), { get signature() { return lastScheduleSignature }, set signature(value) { lastScheduleSignature = value }, get key() { return lastScheduleKey }, set key(value) { lastScheduleKey = value } })); lastScheduleSignature = ''; lastScheduleKey = ''; schedules.value = [saved, ...schedules.value.filter((item) => item.id !== saved.id)]; scheduleConflict.value = null; scheduleConflictPending.value = false; scheduleRebased.value = false; view.value = 'detail' } catch (error) { if (editingSchedule.value && currentSchedule.value && error instanceof AppError && error.status === 409) { scheduleError.value = errorMessage(error); requestId.value = error.requestId ?? ''; scheduleConflictPending.value = true; await retryScheduleConflictLatest(true) } else { setError(error, '日程未保存；草稿仍保留。'); scheduleError.value = loadError.value } } finally { busy.value = false } }
