function discardCheckinDraft() { if (!checkinConflict.value) return; checkinEdit.value = checkinConflict.value; Object.assign(checkinDraft, checkinToDraft(checkinConflict.value)); checkinConflict.value = null; checkinConflictPending.value = false; checkinError.value = '' }
